window.kbPageData["views/entry/k-46946a2a390ef27d"] = {"key":"entry/k-46946a2a390ef27d","state":{"route":"entry/k-46946a2a390ef27d"},"node":{"id":"k-46946a2a390ef27d","mode":"k","title":"两集合容斥原理","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":[],"qs":["国考 2023 地市级 行测#62","国考 2025 副省级 行测#69"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":0,"reviewSet":"多题条目","independentCount":2,"directorySummary":"两个有限集合的并集元素数等于两个集合各自的元素数之和减去交集的元素数，即 |A∪B|＝|A|＋|B|－|A∩B|。","review":{"title":"两集合容斥原理","type":"原理与机制","definition":"两个有限集合的并集元素数等于两个集合各自的元素数之和减去交集的元素数，即 |A∪B|＝|A|＋|B|－|A∩B|。","explanation":"同时属于两个集合的元素在相加时被计入两次，因此要减去一次。若两个集合都包含在同一有限总体内，用总体元素数减去并集元素数，即得两个集合都不属于的元素数。","basis":"据关联原题及所列出处编释。","references":[{"source":"sets","location":"1.4 · 并集和交集"}],"examFocus":{"国考 2023 地市级 行测#62":"分开记录两项都参加、仅参加防病、仅参加育种和均未参加的人数，辨清题中两次比较各涉及哪些人。","国考 2025 副省级 行测#69":"区分两项参与比例之和与至少参与一项的比例，再辨明重叠人数和未参与人数在总人数中的关系。"}},"aspects":[{"title":"由交集与单独人数求两项均未参加人数","uses":[{"unit":"Q1","role":"解题依据","use":"根据多21%和多76人的条件，确定只参加防病、只参加育种、两项都参加的人数分别为100、45、121。从287人中分别扣除，得两项均未参加的有21人。","evidence":"287-100-45-121=21人","qids":["国考 2023 地市级 行测#62"]}]},{"title":"由参与比例和两类人数差求总体","uses":[{"unit":"Q2","role":"解题依据","use":"A、B项目的参与比例之和为105%，超出100%的5个百分点对应两项都参与与两项都不参与的人数差2人，因此小组共有40人。","evidence":"0.6x+0.45x-（y+2）=x-y","qids":["国考 2025 副省级 行测#69"]}]}]},"questions":{"国考 2023 地市级 行测#62":{"paper":"国考 2023 地市级 行测","n":62,"mod":"数量关系","src":["64bc3a15d27a04e94940.pdf",11],"asrc":["f3ab652d8e31c5bbdabc.pdf",19],"card":"238ebb9c2a98a86983a005cd","links":[{"id":"k-46946a2a390ef27d","role":"解题依据","why":"将恰好参加一项的人数和两项都参加的人数各扣除一次，得到两项均未参加的人数。"}]},"国考 2025 副省级 行测#69":{"paper":"国考 2025 副省级 行测","n":69,"mod":"数量关系","src":["ffe12c35a46d4df574ec.pdf",12],"asrc":["ff0b352b44d417525086.pdf",22],"card":"9d817aa16748706d56a815f3","links":[{"id":"k-46946a2a390ef27d","role":"解题依据","why":"至少参加一项的人数等于两个项目人数之和减去重复计入的两项都参加人数。"}]}},"terms":{},"references":{"sets":{"name":"OpenStax《Contemporary Mathematics》两集合的运算","url":"https://openstax.org/books/contemporary-mathematics/pages/1-4-set-operations-with-two-sets"}},"topics":[],"units":{"k-46946a2a390ef27d":[["国考 2023 地市级 行测#62"],["国考 2025 副省级 行测#69"]]}};
